<script setup lang="ts">
import ServerTable from '../../components/ServerTable.vue';
import ActionMenu from "../../components/ActionMenu.vue";
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, reactive, shallowRef } from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import { rupiah } from '../../composables/costing';
type Row = { id: number; nomor: string; jenis: string; judul: string; tgl_mulai: string; tgl_selesai: string; lokasi: string; deal: number; menunggu: number; target_peserta: number; bep: number | null; jumlah_quotation: number; quotation_status: Record<string, number>; can_add: boolean };
const props = defineProps<{ rows: { data: Row[]; total: number; current_page: number; last_page: number; prev_page_url: string | null; next_page_url: string | null }; filters: Record<string, string>; tab: string; stats: { status: string; jumlah: number; peserta: number; nilai: string }[]; years: number[] }>();
const tableStats = shallowRef(props.stats);
const f = reactive({ q: '', jenis: '', tahun: '', bulan: '', status: '', tab: props.tab, ...props.filters });
function search() { router.get('/quotation', f); }
function status(s: string) { f.status = f.status === s ? '' : s; search(); }
const dealRate = computed(() => { const deal = tableStats.value.find((s) => s.status === 'deal')?.jumlah ?? 0; const batal = tableStats.value.find((s) => s.status === 'batal')?.jumlah ?? 0; return deal + batal ? Math.round(deal / (deal + batal) * 100) : null; });
</script>
<template>
    <Head title="Quotation" /><AppLayout title="Quotation" full-width><h1>Daftar Quotation</h1>
        <nav class="tabs" aria-label="Kelompok program"><Link href="/quotation" :aria-current="tab === 'ongoing' ? 'page' : undefined">On going</Link><Link href="/quotation?tab=selesai" :aria-current="tab === 'selesai' ? 'page' : undefined">Selesai (Closed)</Link><Link href="/quotation?tab=data" :aria-current="tab === 'data' ? 'page' : undefined">Data Peserta</Link></nav>
        <form class="filters" @submit.prevent="search"><label>Jenis<select v-model="f.jenis"><option value="">Semua</option><option value="public">Public</option><option value="b2b">B2B</option></select></label><label>Tahun acara<select v-model="f.tahun"><option value="">Semua</option><option v-for="y in years" :key="y" :value="y">{{ y }}</option></select></label><label>Bulan acara<select v-model="f.bulan"><option value="">Semua</option><option v-for="n in 12" :key="n" :value="n">{{ new Date(2026, n - 1).toLocaleString('id-ID', { month: 'long' }) }}</option></select></label><button class="primary">Terapkan</button><Link href="/quotation">Reset</Link></form>
        <div v-if="tab !== 'data'" class="status-summary"><button v-for="s in tableStats" :key="s.status" type="button" :aria-pressed="f.status === s.status" @click="status(s.status)">{{ s.status }}: {{ s.jumlah }} quotation · {{ s.peserta }} peserta<span v-if="s.status === 'deal'"> · {{ rupiah(s.nilai) }}<span v-if="dealRate !== null"> · Tingkat deal {{ dealRate }}%</span></span></button></div>
        <div class="table-wrap"><ServerTable @loaded="result=>{if(result.meta?.stats)tableStats=result.meta.stats as typeof props.stats}" url="/quotation/data" label="Daftar Quotation" :columns='[{"title":"No","orderable":false},{"title":"Penjualan Program","orderable":true},{"title":"Peserta Deal / Target","orderable":true,"className":"dt-body-right"},{"title":"Progres","orderable":false},{"title":"Quotation","orderable":false},{"title":"Aksi","orderable":false}]' :filters="{ ...filters }" refresh-on-visit><template #cell-0="{ number }">{{ number }}</template><template #cell-1="{ row: p, number }">{{ p.nomor }}<small>{{ p.jenis.toUpperCase() }} · {{ p.judul }}</small><small>{{ p.tgl_mulai }} s.d. {{ p.tgl_selesai }} · {{ p.lokasi }}</small></template><template #cell-2="{ row: p, number }">{{ p.deal }} / {{ p.target_peserta }}<small>Menunggu: {{ p.menunggu }} kuota</small></template><template #cell-3="{ row: p, number }"><small>Deal</small><progress :value="p.deal" :max="Math.max(1, p.target_peserta)" :aria-label="`Peserta Deal ${p.nomor}`"></progress><small>Deal + menunggu</small><progress :value="p.deal + p.menunggu" :max="Math.max(1, p.target_peserta)" :aria-label="`Peserta Deal dan kuota menunggu ${p.nomor}`"></progress><small>{{ p.bep === null ? 'BEP tidak tercapai' : `BEP ${p.bep} peserta · ` + (p.deal >= p.bep ? 'Lewat BEP' : `Kurang ${p.bep - p.deal} peserta menuju BEP`) }}</small></template><template #cell-4="{ row: p, number }">{{ p.jumlah_quotation }}<small v-for="s in ['draft', 'terkirim', 'deal', 'batal']" :key="s">{{ s }}: {{ p.quotation_status[s] ?? 0 }}</small></template><template #cell-5="{ row: p, number }"><ActionMenu><Link :href="`/quotation/batch/${p.id}${tab === 'data' ? '?data=1' : ''}`">{{ tab === 'data' ? 'Data Peserta' : 'Lihat detail' }}</Link><p v-if="p.can_add"><Link :href="`/quotation/create?id_penjualan=${p.id}`">Buat Quotation</Link></p></ActionMenu></template></ServerTable></div>
    </AppLayout>
</template>
